async function fetchData(keys=['markets','global','sentiment','news']){
 if(loading)return;loading=true;document.body.classList.add('refreshing');
 await Promise.allSettled(keys.map(async k=>{try{const route=k==='exchange'?'exchange-markets':k;data[k]=await api(route);delete errors[k];}catch(e){errors[k]=e.message;if(data[k])data[k]={...data[k],cache:'stale'};}}));
 loading=false;document.body.classList.remove('refreshing');if(!['terminal'].includes(page))renderPage();else updateWatchPanel();
}
async function loadInstruments(){await Promise.allSettled(['binance','coinbase'].map(async v=>{try{instruments[v]=(await api('instruments?venue='+v)).data;}catch(e){errors['instruments-'+v]=e.message;}}));if(page==='terminal')updateInstrumentOptions();}
function cleanPage(){terminal?.dispose();terminal=null;mini?.remove();mini=null;for(const v of visuals)v.dispose();visuals=[];}
function route(){const hash=location.hash.slice(1).split('?')[0];page=nav.some(x=>x[0]===hash)?hash:'overview';marketPage=0;document.body.classList.remove('menu-open');renderPage();}
