async function loadBenchmark(gen){
 try{const r=await api('candles?venue=binance&symbol=BTCUSDT&interval=1h');if(gen!==pageGeneration||page!=='overview')return;const {createChart,AreaSeries}=await import('lightweight-charts');if(gen!==pageGeneration)return;const bars=r.data.bars;mini=createChart($('#benchmark-chart'),{autoSize:true,layout:{background:{color:'#141915'},textColor:'#85917e',fontSize:10,attributionLogo:true},grid:{vertLines:{visible:false},horzLines:{color:'#242c23'}},rightPriceScale:{borderVisible:false},timeScale:{borderVisible:false,timeVisible:true},crosshair:{vertLine:{color:'#65744e'},horzLine:{color:'#65744e'}}});const series=mini.addSeries(AreaSeries,{lineColor:'#c8f36b',topColor:'#b7e9632a',bottomColor:'#b7e96300',lineWidth:2,priceLineVisible:false,lastValueVisible:false});series.setData(bars.slice(-168).map(b=>({time:b.time,value:b.close})));mini.timeScale().fitContent();$('#benchmark-price').textContent=num(bars.at(-1).close)+' USDT';const change=(bars.at(-1).close/bars.at(-25)?.close-1)*100;$('#benchmark-change').innerHTML=`<span class="${tone(change)}">${pct(change)}</span><small>last 24 candles</small>`;$('#benchmark-source').textContent=`Binance · ${r.cache==='stale'?'Stale snapshot':'Snapshot'} · ${stamp(r.fetchedAt)}`;}catch(e){if(gen===pageGeneration&&$('#benchmark-chart'))$('#benchmark-chart').innerHTML=empty('Benchmark unavailable',e.message);}
}
function marketTable(assets,venue=false){return `<div class="table-scroll"><table class="market-table"><thead><tr><th><span class="sr-only">Watchlist</span></th><th>#</th><th>Asset</th><th>Price ${venue?'(USDT)':'(USD)'}</th><th>24h change</th>${venue?'':'<th>7d change</th><th>Market cap</th>'}<th>24h volume</th><th>Provider time</th><th></th></tr></thead><tbody>${assets.map((a,i)=>`<tr><td><button class="star-button ${workspace.watchlist.includes(a.id)?'selected':''}" data-action="watch" data-id="${esc(a.id)}" aria-label="${workspace.watchlist.includes(a.id)?'Remove':'Add'} ${esc(a.symbol)} ${workspace.watchlist.includes(a.id)?'from':'to'} watchlist" aria-pressed="${workspace.watchlist.includes(a.id)}">${icon('star')}</button></td><td class="muted">${a.rank||'·'}</td><td><button class="asset-name" data-action="${venue?'exchange-chart':'asset-chart'}" data-id="${esc(a.id)}">${coinMark(a.symbol)}<span><strong>${esc(venue?a.symbol:a.name)}</strong><small>${esc(venue?a.name:a.symbol)}</small></span></button></td><td class="mono">${price(a.price,venue?'':'$')}</td><td class="${tone(a.change)} mono">${pct(a.change)}</td>${venue?'':`<td class="${tone(a.change7d)} mono">${pct(a.change7d)}</td><td class="mono">$${compact(a.marketCap)}</td>`}<td class="mono">${venue?'':'$'}${compact(a.volume)}</td><td class="muted tiny" title="${esc(stamp(a.updatedAt))}">${ago(a.updatedAt)}</td><td><button class="icon-button" data-action="${venue?'exchange-chart':'asset-chart'}" data-id="${esc(a.id)}" aria-label="Chart ${esc(a.symbol)}">${icon('arrow-up-right')}</button></td></tr>`).join('')}</tbody></table></div>`;}
function renderMarkets(){
 $('#main').innerHTML=header('The crypto market.','Search the available directory. Separate aggregate valuations from exchange prices.',`<button class="button" data-action="export-markets">${icon('download')} Export results</button>`)+`<div class="panel"><div class="market-controls"><div class="tabs"><button class="tab ${marketUniverse==='aggregate'?'active':''}" data-action="universe" data-universe="aggregate">Asset directory <span>USD</span></button><button class="tab ${marketUniverse==='exchange'?'active':''}" data-action="universe" data-universe="exchange">Binance spot <span>USDT</span></button></div><label class="search-field">${icon('search')}<input id="market-search" placeholder="Search name, symbol or asset ID" value="${esc(marketQuery)}" aria-label="Search markets"></label></div><div class="filter-row"><button class="chip ${onlyWatch?'selected':''}" data-action="toggle-watch">${icon('star')} Watchlist only</button><label class="sort-label">Sort by <select id="market-sort"><option value="rank">${marketUniverse==='exchange'?'Volume':'Rank'}</option><option value="marketCap">Market cap</option><option value="volume">24h volume</option><option value="gainers">Top gainers</option><option value="losers">Top losers</option></select></label><span id="market-source"></span></div><div id="market-results"></div><div id="market-pagination" class="pagination"></div></div><p class="data-note">Asset directory: Powered by Coinpaprika. Free snapshots may lag by up to 10 minutes. A listing is not a credibility endorsement. Binance spot covers that venue's USDT markets only. Open the explicitly labeled instrument for live charts.</p>`;
 $('#market-sort').value=marketSort;$('#market-search').addEventListener('input',e=>{marketQuery=e.target.value;marketPage=0;renderMarketResults();});$('#market-sort').addEventListener('change',e=>{marketSort=e.target.value;marketPage=0;renderMarketResults();});renderMarketResults();if(marketUniverse==='exchange'&&!data.exchange)fetchData(['exchange']);
}
function filteredMarkets(){const list=[...(marketUniverse==='exchange'?data.exchange?.data??[]:data.markets?.data??[])].filter(a=>(!onlyWatch||workspace.watchlist.includes(a.id))&&`${a.name} ${a.symbol} ${a.id}`.toLowerCase().includes(marketQuery.toLowerCase()));if(marketSort==='marketCap')list.sort((a,b)=>(b.marketCap??0)-(a.marketCap??0));if(marketSort==='volume')list.sort((a,b)=>b.volume-a.volume);if(marketSort==='gainers')list.sort((a,b)=>(b.change??-Infinity)-(a.change??-Infinity));if(marketSort==='losers')list.sort((a,b)=>(a.change??Infinity)-(b.change??Infinity));return list;}
function renderMarketResults(){const key=marketUniverse==='exchange'?'exchange':'markets';const list=filteredMarkets(),pages=Math.max(1,Math.ceil(list.length/40));marketPage=Math.min(marketPage,pages-1);$('#market-results').innerHTML=list.length?marketTable(list.slice(marketPage*40,marketPage*40+40),marketUniverse==='exchange'):data[key]?empty('No assets match your filters','Try a name, ticker or a different universe.'):errorOrLoading(key);$('#market-source').innerHTML=stateBadge(key);$('#market-pagination').innerHTML=`<span>${num(list.length,0)} results · Page ${marketPage+1} of ${pages}</span><div><button class="icon-button" data-action="prev-page" aria-label="Previous page" ${marketPage===0?'disabled':''}>${icon('chevron-left')}</button><button class="icon-button" data-action="next-page" aria-label="Next page" ${marketPage>=pages-1?'disabled':''}>${icon('chevron-right')}</button></div>`;hydrate();}
